#!/usr/bin/env bash
# GeoSpaX Field for Android: build and sign the APK (apps/field).
#
#   scripts/package-android.sh [OUT_DIR]             default OUT_DIR: releases/
#   scripts/package-android.sh --emulator [OUT_DIR]  a debug x86_64 APK for the Android emulator (CI test);
#                                                    WebView debugging on, signed with the debug key
#
# Needs the Android SDK and NDK (ANDROID_HOME, NDK_HOME), Java 17, Rust with the Android targets and Node.
# The Android project (apps/field/src-tauri/gen/android) is generated by `tauri android init` and given the
# location permission here. The APK covers 64-bit and 32-bit ARM phones.
#
# Signing: with ANDROID_KEYSTORE (path to a .jks), ANDROID_KEYSTORE_PASSWORD and ANDROID_KEY_ALIAS the APK is
# signed with that key, so phones accept it as an update of the previous one. Without them a throwaway key
# is made: the APK installs, but the next build cannot update it (uninstall first).
set -euo pipefail
cd "$(dirname "$0")/.."
EMULATOR=
if [ "${1:-}" = --emulator ]; then EMULATOR=1; shift; fi
OUT="$(realpath -m "${1:-releases}")"
ROOT=$PWD
VERSION=$(python3 -c 'import json;print(json.load(open("apps/field/src-tauri/tauri.conf.json"))["version"])')
: "${ANDROID_HOME:?set ANDROID_HOME to the Android SDK}"
: "${NDK_HOME:?set NDK_HOME to the Android NDK}"

cd apps/field
[ -d node_modules ] || npm ci --no-audit --no-fund
if [ ! -d src-tauri/gen/android ]; then
  echo "== tauri android init"
  npx tauri android init --ci
fi
# the launcher icon is the GeoSpaX logo, the same as the desktop app's (tauri android init puts Tauri's
# own icon there). android-launcher.png is that logo with the padding Android's adaptive icons need
# (phones show the middle two thirds, as a circle or squircle), on a white background
echo "== launcher icon"
ICONS=$(mktemp -d)
npx tauri icon src-tauri/icons/android-launcher.png -o "$ICONS" >/dev/null
cp -r "$ICONS/android/." src-tauri/gen/android/app/src/main/res/
rm -rf "$ICONS"
MANIFEST=src-tauri/gen/android/app/src/main/AndroidManifest.xml
for perm in ACCESS_FINE_LOCATION ACCESS_COARSE_LOCATION CAMERA RECORD_AUDIO MODIFY_AUDIO_SETTINGS; do
  grep -q "android.permission.$perm" "$MANIFEST" || \
    sed -i "s|<application|<uses-permission android:name=\"android.permission.$perm\" />\n    <application|" "$MANIFEST"
done
grep -q 'android.hardware.location.gps' "$MANIFEST" || \
  sed -i 's|<application|<uses-feature android:name="android.hardware.location.gps" android:required="false" />\n    <application|' "$MANIFEST"

if [ -n "$EMULATOR" ]; then
  echo "== debug APK for the emulator (x86_64)"
  npx tauri android build --debug --apk --target x86_64 --ci
  APK=$(find src-tauri/gen/android/app/build/outputs/apk -name '*debug*.apk' | head -1)
  [ -n "$APK" ] || { echo "no APK built"; exit 1; }
  mkdir -p "$OUT"
  cp "$APK" "$OUT/GeoSpaX-Field-emulator.apk"
  echo "== $OUT/GeoSpaX-Field-emulator.apk"
  exit 0
fi

echo "== APK (aarch64 + armv7)"
# one Rust build at a time: in parallel, the two targets' Tauri plugin build scripts copy the same
# tauri-api build folder at once and one fails ("failed to copy tauri-api to the plugin project")
export GRADLE_OPTS="${GRADLE_OPTS:-} -Dorg.gradle.workers.max=1 -Dorg.gradle.parallel=false"
export CARGO_BUILD_JOBS="${CARGO_BUILD_JOBS:-$(nproc)}"
npx tauri android build --apk --target aarch64 armv7 --ci
APK=$(find src-tauri/gen/android/app/build/outputs/apk -name '*release*.apk' | head -1)
[ -n "$APK" ] || { echo "no APK built"; exit 1; }

echo "== signing"
BT=$(ls -d "$ANDROID_HOME"/build-tools/* | sort -V | tail -1)
KS="${ANDROID_KEYSTORE:-}"
if [ -z "$KS" ]; then
  KS=$(mktemp -d)/throwaway.jks
  ANDROID_KEYSTORE_PASSWORD=throwaway ANDROID_KEY_ALIAS=geospax-field
  keytool -genkeypair -keystore "$KS" -storepass throwaway -keypass throwaway -alias geospax-field \
    -keyalg RSA -keysize 2048 -validity 10000 -dname "CN=GeoSpaX Field (unofficial build)" >/dev/null 2>&1
  echo "   (no ANDROID_KEYSTORE: signed with a throwaway key; later builds cannot update this one)"
fi
mkdir -p "$OUT"
DEST="$OUT/GeoSpaX-Field-$VERSION.apk"
"$BT/zipalign" -f -p 4 "$APK" "$DEST.aligned"
"$BT/apksigner" sign --ks "$KS" --ks-pass "pass:$ANDROID_KEYSTORE_PASSWORD" --ks-key-alias "$ANDROID_KEY_ALIAS" --out "$DEST" "$DEST.aligned"
rm -f "$DEST.aligned" "$DEST.idsig"
"$BT/apksigner" verify "$DEST"
echo "== $DEST ($(du -h "$DEST" | cut -f1))"
cd "$ROOT"
